arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel,private_channel","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for c in d['channels']:
    if c['name'] in ('incidents','incident-response'):
        print(c['id'], c['name'], 'is_private' if c.get('is_private') else 'public')
"

